mapper.select:
where i.del_flag = '0'
and ( i.oe_item_name like concat('%', #{keyword}, '%') or i.oe_item_code like concat('%', #{keyword}, '%') or i.oe_type_name like concat('%', #{keyword}, '%') or i.supplier_name like concat('%', #{keyword}, '%') )
and i.oe_item_name like concat('%', #{oeItemName}, '%') and i.oe_item_code = #{oeItemCode} and i.oe_type_name like concat('%', #{oeTypeName}, '%') and i.supplier_name like concat('%', #{supplierName}, '%') and (i.category_id = #{categoryId} or find_in_set(#{categoryId}, c.ancestors)) and i.status = #{status}
and = #{purchaseReferenceStatus}
order by i.create_time desc, i.oe_item_id desc


where i.del_flag = '0'
  and i.category_id = #{categoryId}
  and ifnull(i.oe_type_name, '') = ifnull(#{oeTypeName}, '')
  and i.oe_item_name = #{oeItemName}
  and ifnull(i.item_description, '') = ifnull(#{itemDescription}, '')
limit 1

select count(1)
from inv_oe_item
where del_flag = '0'
  and oe_item_code = #{oeItemCode}
and oe_item_id != #{excludeOeItemId}

select count(1)
from oa_fixed_asset_config
where oe_item_id = #{oeItemId}
